def change(n,question=None,options=None,answer=None,reason=None,tip=None,note='',priority='required',alternatives=None,source=None):
 q=by[f'COS201-{n}'];changes={}
 if question is not None:changes['question']=question
 if options is not None:changes['options']=options
 if answer is not None:changes['answer']=answer
 proposals.append({'id':q['id'],'priority':priority,'original':{k:q[k] for k in ['question','options','answer']},'changes':changes,'reason':reason or why[n],'tip':tip or '', 'note':note or why[n],'originalAcceptedAlternatives':alternatives or [],'references':([S[source]] if source else refs[n])})
def opt(n,index,value):
 a=list(by[f'COS201-{n}']['options']);a[index]=value;return a

for n in [802,968]:change(n,question='For coherent BPSK over AWGN, why does the BER decrease approximately exponentially at high Eb/N0?',reason='Với BPSK đồng bộ trong AWGN, Pb=Q(√(2Eb/N0)); phần đuôi Q giảm gần theo hàm mũ khi Eb/N0 lớn.',tip='BPSK + AWGN + high SNR → Q-tail, không áp dụng cho mọi kênh.')
for n,idx in [(804,1),(1014,1)]:change(n,options=opt(n,idx,'Regenerative decisions limit accumulated analog noise, although decision errors remain possible'),reason='Tái tạo các mức số hạn chế cộng dồn nhiễu tương tự; nhiễu đủ lớn vẫn gây quyết định sai.',tip='digital regeneration → hạn chế noise accumulation, không miễn nhiễm mọi nhiễu.')
change(806,options=opt(806,1,'Phase error grows continuously because the frequencies remain different'),reason='PLL khóa khi hai tần số bám nhau và sai lệch pha hằng; hằng đó có thể bằng zero.',tip='locked → constant phase error, không bắt buộc zero.',alternatives=[[1],[2]],note='Original B (constant) and C (zero or constant) overlap; repair B while preserving key C.')
for n,idx in [(812,1),(996,2)]:change(n,options=opt(n,idx,'One bit indicating the sign of the difference between the input sample and its predicted value'),reason='DM cơ bản gửi một bit chỉ chiều tăng/giảm so với mức dự đoán, không gửi toàn bộ hiệu số.',tip='DM → 1-bit sign of prediction error.')
change(816,question='For an ideal FM discriminator operating above threshold with white input noise, the post-detection noise power integrated over a message bandwidth W grows proportional to:',reason='PSD nhiễu sau discriminator tỷ lệ f²; tích phân từ 0 đến W cho hệ số W³.',tip='Above threshold: ∫₀ᵂ f²df → W³.')
for n in [827,1010]:change(n,question='Compared with coherent antipodal BPSK at the same BER in AWGN, why does coherent orthogonal BFSK require about 3 dB more Eb/N0?',reason='Ở cùng Eb, d² của BFSK trực giao là 2Eb, còn BPSK đối cực là 4Eb; cần gấp đôi Eb ≈ 3 dB.',tip='coherent orthogonal BFSK vs BPSK → 3 dB, cùng BER/AWGN.')
change(829,question='When an LZ-type compressor is allowed a larger dictionary, which statement is generally valid?',options=by['COS201-829']['options']+['Compression may improve through longer matches, but index/memory overhead also grows; the compression ratio is not guaranteed to increase.'],answer=[4],reason='Từ điển lớn có thể tìm được chuỗi khớp dài hơn nhưng cần chỉ mục dài hơn và thêm bộ nhớ. Tỷ lệ nén không tăng đơn điệu với mọi dữ liệu.',tip='LZ dictionary lớn → tradeoff, không bảo đảm ratio tăng.',source='lz')
for n in [832,1004]:change(n,question='For a known deterministic signal in white additive noise, why does a matched filter maximize the sampled output SNR?',reason='Bất đẳng thức Cauchy–Schwarz đạt dấu bằng khi bộ lọc là phiên bản đảo thời gian/liên hợp của tín hiệu cần thu.',tip='Matched filter tối ưu SNR trong white noise.',priority='clarify')
change(837,question='In an uncompensated link without a zero-ISI pulse-shaping design, which channel property commonly causes symbol pulses to spread and overlap?',reason='Giới hạn băng có thể làm xung trải dài; thiết kế Nyquist đúng vẫn có thể triệt ISI tại thời điểm lấy mẫu.',tip='band limit + không bù/tạo xung đúng → có thể ISI, không phải luôn luôn.')
for n in [845,902]:change(n,question='For conventional AM with a single sinusoidal message, what is the maximum sideband-to-total power efficiency without overmodulation (0 ≤ μ ≤ 1)?',reason='AM một tone có η=μ²/(2+μ²); tại μ=1 đạt 1/3. Không suy rộng 1/3 cho mọi dạng thông điệp hay mọi định nghĩa FOM.',tip='Single-tone AM, μ=1 → ηmax=1/3.')
change(851,question='In coherent DSB-SC product detection of a single message branch, a 90° carrier-reference phase error makes the recovered message component:',reason='Thành phần thông điệp ở đầu ra tỷ lệ cosφ; cos90°=0. Với thu I/Q tổng quát, lệch pha làm quay chòm sao.',tip='DSB-SC single-branch: 90° → cos90°=0.')
