change(879,question='Which standard integrability condition guarantees an ordinary Fourier transform for a signal?',options=opt(879,1,'Growing as exp(t²) over the whole real line'),reason='Khả tích tuyệt đối là điều kiện đủ cho FT thường. Tín hiệu zero trong lựa chọn cũ cũng có FT, nên cặp lựa chọn cũ không duy nhất.',tip='Ordinary FT sufficient condition → ∫|x(t)|dt < ∞.',alternatives=[[1],[2]])
