change(883,question='In WLAN frequency-domain zero-forcing equalization, when H_k ≠ 0, which operation compensates the multiplicative channel response?',reason='Với Yk=HkXk+Nk, zero forcing nhân Yk với 1/Hk. Gần điểm triệt kênh sẽ khuếch đại nhiễu; Hk=0 không nghịch đảo được.',tip='Zero forcing → Yk/Hk, chỉ khi Hk≠0.')
change(892,question='Which modulation is used by the legacy ATSC 1.0 terrestrial digital-TV physical layer?',reason='ATSC 1.0 dùng 8-VSB; ATSC 3.0 dùng OFDM, nên không gọi chung mọi ATSC hiện đại là 8-VSB.',tip='ATSC 1.0 → 8-VSB; ATSC 3.0 → OFDM.',source='atsc')
