for n in [903,971]:change(n,question='For a real baseband signal occupying [−W, W], which inequality describes the full undersampling range that violates the Nyquist bound (rather than just one special sampling rate)?',reason='Dải vi phạm tổng quát là fs<2W. fs=W chỉ là một trường hợp nằm trong dải đó, nên đề cũ có hai lựa chọn đúng theo nghĩa “xảy ra khi”.',tip='Full range → fs<2W; fs=W chỉ là trường hợp riêng.',alternatives=[[0],[1]])
change(914,question='For an ideal uniform quantizer in the high-resolution regime, SNR ∝ 2^(2R) implies what type of growth with bits per sample R?',reason='2^(2R)=4^R là hàm mũ; thêm một bit làm SNR lý tưởng nhân 4, tương đương khoảng 6,02 dB.',tip='+1 bit → ×4 linear SNR → +6,02 dB.')
