change(964,question='For an alphabet of exactly 2^k equally likely symbols, what codeword-length pattern does optimal binary Huffman coding produce?',reason='Có 2^k ký hiệu đồng xác suất thì mọi từ mã dài k bit. Nếu có 3 ký hiệu đồng xác suất, độ dài 1,2,2 là phản ví dụ cho đề cũ.',tip='Equal probabilities + 2^k symbols → fixed length k.',alternatives=[[2],[3]])
change(965,options=opt(965,3,'Delta is small while the input remains constant'),reason='Định nghĩa quá tải dốc là |dx/dt|>Δ/T. Bước nhỏ trên đoạn đầu vào hằng không tự gây quá tải dốc.',tip='Slope overload → input slope > Δ/T.',alternatives=[[1],[3]])
