for n,correct,alt in [(991,1,2),(1005,0,3)]:
 change(n,question='For equally likely antipodal binary levels −A and +A in zero-mean AWGN of equal variance, what is the numerical optimal decision threshold?',options=opt(n,alt,'A/2'),reason='Hai mức đối xứng, xác suất bằng nhau và nhiễu đối xứng cho ngưỡng 0. “Average value” cũ có thể cũng chỉ trung điểm bằng 0.',tip='Equal-prior ±A + symmetric AWGN → threshold 0.',alternatives=[[correct],[alt]])
change(995,question='With noise spectral density N0 held fixed, if bit energy Eb doubles, what happens to the linear ratio Eb/N0?',reason='N0 không đổi thì Eb/N0 nhân 2, tương đương tăng 3,0103 dB.',tip='Fixed N0: ×2 Eb → ×2 Eb/N0 → +3 dB.')
change(998,question='For known source-symbol probabilities, why is binary Huffman coding optimal among binary prefix codes that encode one symbol at a time?',reason='Huffman tối thiểu hóa độ dài mã kỳ vọng trong lớp mã prefix theo ký hiệu. Không khẳng định thắng mọi mã khối hoặc arithmetic coding.',tip='Huffman optimal → symbol-by-symbol binary prefix code.')
change(1006,question='At fixed average symbol energy and AWGN level, why does increasing square M-QAM order generally increase the error probability?',priority='clarify')
change(1009,options=opt(1009,1,'Not decrease; guaranteed correction is t = floor((d_min − 1)/2), so some increases leave t unchanged'),reason='Số lỗi bảo đảm sửa được t=⌊(dmin−1)/2⌋. Tăng dmin từ 3 lên 4 vẫn chỉ sửa được 1 lỗi, nên không luôn tăng nghiêm ngặt.',tip='Correct t errors ↔ dmin≥2t+1; t tăng theo bậc thang.',alternatives=[[0],[1]])
change(1011,question='At a fixed symbol rate Rs, what happens to the possibility of zero-ISI baseband transmission if available ideal bandwidth is below Rs/2?',options=opt(1011,0,'Zero-ISI pulse shaping is no longer possible at that symbol rate'),reason='Tiêu chuẩn Nyquist yêu cầu B≥Rs/2 để có truyền không ISI lý tưởng; băng thấp hơn không đáp ứng ở cùng tốc độ symbol.',tip='Nyquist zero-ISI bound → B≥Rs/2.')
change(1013,question='In conventional passband radio communication, why are baseband messages translated onto an RF carrier?',options=opt(1013,0,'To support efficient practical antenna radiation and use an allocated RF band'),reason='Sóng mang đưa thông điệp vào dải RF phù hợp anten và phân kênh; không phải mọi đường truyền baseband đều bắt buộc điều chế lên RF.',tip='Passband radio → practical antenna + allocated RF band.')

